Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Distance <i>r</i> from source: <b><span id="rVal">3.00</span></b>
  <input id="distance" type="range" min="3" max="6" step="0.05" value="3">
</label>
<div style="display:flex;gap:4px;flex-wrap:wrap">
  <button id="ovArea" class="active">Area A(r)</button>
  <button id="ovInt">Intensity I(r)</button>
</div>
<div id="readout" style="font:12px/1.6 ui-monospace,Consolas,monospace;border:1px solid #dcdfe3;border-radius:4px;padding:6px 8px;background:#fff"></div>
<div style="font-size:11px;color:#555;margin-top:2px">Guided demo</div>
<div style="display:flex;gap:4px">
  <button id="stepPrev">◀ Prev</button>
  <button id="stepPlay">Play</button>
  <button id="stepNext">Next ▶</button>
</div>
<div id="stepTitle" style="font-size:11px;font-weight:bold"></div>
<div id="narr" style="font-size:11px;line-height:1.45;color:#333"></div>
<div style="font-size:10px;color:#777;line-height:1.4;margin-top:4px">Drag to orbit: the patches are real flat squares cut from a solid cone of rays.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ────────────────────────────────────────────────────────
   source dot        → SphereGeometry(0.06)                       black
   wavy leader       → Line (sine-perturbed polyline) + cone tip  black
   4 solid rays      → Line  origin → live patch corner           #4A7F9B
   4 dashed rays     → Line + LineDashedMaterial → A2 corner      #4A7F9B
   ghost A1 / A2     → PlaneGeometry quad + edge outline          #7BA7BC / #4A7F9B
   live patch A(r)   → PlaneGeometry(1,1) scaled 0.20r, LineLoop outline
   r1 / r2 measures  → Line along AX + 2 cones + 2 tick bars      black
   curved leaders    → QuadraticBezierCurve3 Line + cone tip      black
   labels            → addLabel HTML (serif italic)
  ───────────────────────────────────────────────────────────────────────── */

const COL_STROKE = 0x4a7f9b, COL_FILL = 0x7ba7bc, BLACK = 0x000000;
const R1 = 3.0, R2 = 6.0, KSIDE = 0.20;

const AX  = new THREE.Vector3(0.62, 0.66, 0.42).normalize();
const WUP = new THREE.Vector3(0, 1, 0);
const PU  = WUP.clone().addScaledVector(AX, -WUP.dot(AX)).normalize();   // patch local up
const PR  = new THREE.Vector3().crossVectors(PU, AX).normalize();        // patch local right
const OFF = new THREE.Vector3(0.55, -0.62, 0).normalize();               // measuring offset dir
const PQ  = new THREE.Quaternion().setFromRotationMatrix(
  new THREE.Matrix4().makeBasis(PR, PU, AX));
const ORG = new THREE.Vector3(0, 0, 0);

function patchCenter(r) { return AX.clone().multiplyScalar(r); }
function patchCorners(r) {
  const h = KSIDE * r * 0.5, c = patchCenter(r);
  return [[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([a, b]) =>
    c.clone().addScaledVector(PR, a * h).addScaledVector(PU, b * h));
}

/* ── helpers ───────────────────────────────────────────────────────────── */
function lineFrom(pts, mat) {
  const g = new THREE.BufferGeometry().setFromPoints(pts);
  const l = new THREE.Line(g, mat);
  if (mat.isLineDashedMaterial) l.computeLineDistances();
  scene.add(l); return l;
}
function setLinePts(line, pts) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}
function coneAt(tip, dir, color, len = 0.20, rad = 0.065) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, len, 14),
    new THREE.MeshBasicMaterial({ color }));
  const dn = dir.clone().normalize();
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dn);
  m.position.copy(tip).addScaledVector(dn, -len / 2);
  scene.add(m); return m;
}
function curvedArrow(from, to, bulgeDir, bulge) {
  const mid = from.clone().add(to).multiplyScalar(0.5).addScaledVector(bulgeDir, bulge);
  const curve = new THREE.QuadraticBezierCurve3(from, mid, to);
  const pts = curve.getPoints(28);
  lineFrom(pts, new THREE.LineBasicMaterial({ color: BLACK }));
  const tail = pts[pts.length - 2], head = pts[pts.length - 1];
  coneAt(head, head.clone().sub(tail), BLACK, 0.18, 0.055);
}

/* ── source dot ────────────────────────────────────────────────────────── */
const dot = new THREE.Mesh(new THREE.SphereGeometry(0.07, 20, 16),
  new THREE.MeshBasicMaterial({ color: BLACK }));
scene.add(dot);
registerInteractive(dot, {
  title: 'Radio source',
  tooltip: 'Point source of radiation',
  body: 'A point transmitter radiating power P. Every ray in the bundle carries a fixed share of that power, no matter how far it travels.'
});

/* ── wavy leader to "Radio source" text ────────────────────────────────── */
const wStart = new THREE.Vector3().addScaledVector(PR, -1.55).addScaledVector(PU, -0.55);
const wEnd   = new THREE.Vector3().addScaledVector(PR, -0.28).addScaledVector(PU, -0.14);
const wPts = [];
for (let i = 0; i <= 44; i++) {
  const t = i / 44;
  const p = wStart.clone().lerp(wEnd, t).addScaledVector(PU, 0.11 * Math.sin(t * Math.PI * 3));
  wPts.push(p);
}
lineFrom(wPts, new THREE.LineBasicMaterial({ color: BLACK }));
coneAt(ORG.clone().addScaledVector(PR, -0.10).addScaledVector(PU, -0.05),
  ORG.clone().sub(wEnd), BLACK, 0.18, 0.055);

/* ── ghost reference patches at the two stations ───────────────────────── */
function ghostPatch(r, dashed) {
  const grp = new THREE.Group();
  const s = KSIDE * r;
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(1, 1),
    new THREE.MeshBasicMaterial({
      color: COL_FILL, transparent: true, opacity: 0.30, side: THREE.DoubleSide,
      depthWrite: false, polygonOffset: true, polygonOffsetFactor: 2, polygonOffsetUnits: 2
    }));
  fill.scale.set(s, s, 1);
  grp.add(fill);
  const cs = patchCorners(r); cs.push(cs[0].clone());
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color: COL_STROKE, dashSize: 0.13, gapSize: 0.10 })
    : new THREE.LineBasicMaterial({ color: COL_STROKE });
  const outline = new THREE.Line(new THREE.BufferGeometry().setFromPoints(cs), mat);
  if (dashed) outline.computeLineDistances();
  grp.add(outline);
  grp.position.copy(patchCenter(r));
  fill.position.set(0, 0, 0);
  outline.position.copy(patchCenter(r)).multiplyScalar(-1);
  grp.quaternion.copy(PQ);
  // outline was built in world coords: undo the group transform for it
  outline.position.set(0, 0, 0);
  outline.geometry.dispose();
  const local = [];
  for (const c of cs) local.push(new THREE.Vector3(
    c.clone().sub(patchCenter(r)).dot(PR),
    c.clone().sub(patchCenter(r)).dot(PU), 0));
  outline.geometry = new THREE.BufferGeometry().setFromPoints(local);
  if (dashed) outline.computeLineDistances();
  scene.add(grp);
  registerInteractive(fill, {
    title: r === R1 ? 'Patch A₁' : 'Patch A₂',
    tooltip: r === R1 ? 'Near station, r₁ = 3' : 'Far station, r₂ = 6',
    body: r === R1
      ? 'At r₁ the ray bundle intercepts a square of side 0.20·r₁ = 0.60, area A₁ = 0.36.'
      : 'At r₂ = 2r₁ the same bundle spans a square of side 1.20 — twice the side, four times the area: A₂ = 4A₁.'
  });
  return grp;
}
ghostPatch(R1, false);
ghostPatch(R2, true);

/* ── live sliding patch ────────────────────────────────────────────────── */
const liveMat = new THREE.MeshBasicMaterial({
  color: COL_FILL, transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false
});
const livePatch = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), liveMat);
livePatch.quaternion.copy(PQ);
scene.add(livePatch);
registerInteractive(livePatch, {
  title: 'Sampling patch A(r)',
  tooltip: 'Slide it with the Distance control',
  body: 'This square always exactly fills the fixed cone of four rays. Its side grows as 0.20·r, so A(r) = (0.20r)² ∝ r², and the intensity I = P/A falls off as 1/r².'
});
const outlineMat = new THREE.LineBasicMaterial({ color: COL_STROKE });
const liveOutline = lineFrom(patchCorners(R1).concat([patchCorners(R1)[0]]), outlineMat);

/* ── rays: solid to the live patch, dashed out to A2 ───────────────────── */
const C2 = patchCorners(R2);
const solidRays = [], dashRays = [];
for (let i = 0; i < 4; i++) {
  solidRays.push(lineFrom([ORG, patchCorners(R1)[i]],
    new THREE.LineBasicMaterial({ color: COL_STROKE })));
  dashRays.push(lineFrom([patchCorners(R1)[i], C2[i]],
    new THREE.LineDashedMaterial({ color: COL_STROKE, dashSize: 0.13, gapSize: 0.10 })));
}

/* ── measuring arrows r1, r2 ───────────────────────────────────────────── */
function measureArrow(rEnd, offAmt) {
  const a = ORG.clone().addScaledVector(OFF, offAmt);
  const b = patchCenter(rEnd).addScaledVector(OFF, offAmt);
  lineFrom([a, b], new THREE.LineBasicMaterial({ color: BLACK }));
  coneAt(a, a.clone().sub(b), BLACK, 0.22, 0.07);
  coneAt(b, b.clone().sub(a), BLACK, 0.22, 0.07);
  const tick = 0.30;
  for (const p of [a, b]) {
    lineFrom([p.clone().addScaledVector(PU, -tick), p.clone().addScaledVector(PU, tick)],
      new THREE.LineBasicMaterial({ color: BLACK }));
  }
  return a.clone().lerp(b, 0.5);
}
const mid1 = measureArrow(R1, 0.9);
const mid2 = measureArrow(R2, 1.8);

/* ── curved leader arrows for A1 / A2 ──────────────────────────────────── */
const a1Anchor = patchCenter(R1).addScaledVector(PU, 0.95).addScaledVector(PR, -1.15);
const a1Target = patchCorners(R1)[1].clone().lerp(patchCenter(R1), 0.25).addScaledVector(PU, 0.06);
curvedArrow(a1Anchor.clone().addScaledVector(PR, 0.22), a1Target, PU, 0.28);

const a2Anchor = patchCenter(R2).addScaledVector(PU, 1.05).addScaledVector(PR, 1.25);
const a2Target = patchCorners(R2)[0].clone().lerp(patchCenter(R2), 0.30).addScaledVector(PU, 0.05);
curvedArrow(a2Anchor.clone().addScaledVector(PR, -0.22), a2Target, PU, 0.28);

/* ── camera (after all geometry) ───────────────────────────────────────── */
