  solidRays.push(lineFrom([ORG, patchCorners(R1)[i]],
    new THREE.LineBasicMaterial({ color: COL_STROKE })));
  dashRays.push(lineFrom([patchCorners(R1)[i], C2[i]],
    new THREE.LineDashedMaterial({ color: COL_STROKE, dashSize: 0.13, gapSize: 0.10 })));
}

/* ── measuring arrows r1, r2 ───────────────────────────────────────────── */
function measureArrow(rEnd, offAmt) {
  const a = ORG.clone().addScaledVector(OFF, offAmt);
  const b = patchCenter(rEnd).addScaledVector(OFF, offAmt);
  lineFrom([a, b], new THREE.LineBasicMaterial({ color: BLACK }));
  coneAt(a, a.clone().sub(b), BLACK, 0.22, 0.07);
  coneAt(b, b.clone().sub(a), BLACK, 0.22, 0.07);
  const tick = 0.30;
  for (const p of [a, b]) {
    lineFrom([p.clone().addScaledVector(PU, -tick), p.clone().addScaledVector(PU, tick)],
      new THREE.LineBasicMaterial({ color: BLACK }));
  }
  return a.clone().lerp(b, 0.5);
}
const mid1 = measureArrow(R1, 0.9);
const mid2 = measureArrow(R2, 1.8);

/* ── curved leader arrows for A1 / A2 ──────────────────────────────────── */
const a1Anchor = patchCenter(R1).addScaledVector(PU, 0.95).addScaledVector(PR, -1.15);
const a1Target = patchCorners(R1)[1].clone().lerp(patchCenter(R1), 0.25).addScaledVector(PU, 0.06);
curvedArrow(a1Anchor.clone().addScaledVector(PR, 0.22), a1Target, PU, 0.28);

const a2Anchor = patchCenter(R2).addScaledVector(PU, 1.05).addScaledVector(PR, 1.25);
const a2Target = patchCorners(R2)[0].clone().lerp(patchCenter(R2), 0.30).addScaledVector(PU, 0.05);
curvedArrow(a2Anchor.clone().addScaledVector(PR, -0.22), a2Target, PU, 0.28);

/* ── camera (after all geometry) ───────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 40, elevationDeg: 18, rollDeg: 0, heightFraction: 0.65 });
controls.minPolarAngle = THREE.MathUtils.degToRad(35);
controls.maxPolarAngle = THREE.MathUtils.degToRad(85);
controls.minAzimuthAngle = THREE.MathUtils.degToRad(15);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(85);
controls.update();
document.getElementById('btnReset').style.display = '';

/* ── labels ────────────────────────────────────────────────────────────── */
const SER = 'font-family:Georgia,\'Times New Roman\',serif;font-style:italic';
addLabel(`<span style="${SER}">A</span><sub>1</sub>`, a1Anchor, { fontSize: '17px' });
addLabel(`<span style="${SER}">A</span><sub>2</sub>`, a2Anchor, { fontSize: '17px' });
addLabel(`<span style="${SER}">r</span><sub>1</sub>`,
  mid1.clone().addScaledVector(PU, 0.30), { fontSize: '16px' });
addLabel(`<span style="${SER}">r</span><sub>2</sub>`,
  mid2.clone().addScaledVector(PU, 0.30), { fontSize: '16px' });
addLabel('Radio<br>source', wStart, { fontSize: '14px', offset: [-22, 12] });
const liveLbl = addLabel('', patchCenter(R1), {
  fontSize: '13px', color: '#14536e', bold: true, background: 'rgba(255,255,255,0.86)'
});

/* ── state + update ────────────────────────────────────────────────────── */
let curR = R1;
let mode = 'area';
const A1 = (KSIDE * R1) ** 2;

const elR = document.getElementById('distance');
const elRVal = document.getElementById('rVal');
const elRead = document.getElementById('readout');
const btnArea = document.getElementById('ovArea');
const btnInt = document.getElementById('ovInt');

function update() {
  const r = curR, s = KSIDE * r;
  const A = s * s, Aratio = A / A1, I = (R1 / r) ** 2;

  livePatch.position.copy(patchCenter(r));
  livePatch.scale.set(s, s, 1);

  const cs = patchCorners(r);
  setLinePts(liveOutline, cs.concat([cs[0]]));
  for (let i = 0; i < 4; i++) {
    setLinePts(solidRays[i], [ORG, cs[i]]);
    setLinePts(dashRays[i], [cs[i], C2[i]]);
  }

  if (mode === 'area') {
    liveMat.opacity = 0.55;
    liveMat.color.setHex(COL_FILL);
    outlineMat.color.setHex(0x1f5f80);
    liveLbl.div.style.color = '#14536e';
    liveLbl.div.innerHTML =
      `<span style="${SER}">A</span>(<span style="${SER}">r</span>) = ${A.toFixed(2)} = ${Aratio.toFixed(2)}&times;<span style="${SER}">A</span><sub>1</sub>`;
  } else {
    liveMat.opacity = 0.12 + 0.48 * I;
    liveMat.color.setHex(0xc0533a);
    outlineMat.color.setHex(0xa8442c);
    liveLbl.div.style.color = '#8e3620';
    liveLbl.div.innerHTML =
      `<span style="${SER}">I</span>(<span style="${SER}">r</span>) = ${I.toFixed(2)} <span style="${SER}">I</span><sub>1</sub>`;
  }
  liveLbl.pos.copy(patchCenter(r)).addScaledVector(PR, 0.10 * r + 0.55);

  elRVal.textContent = r.toFixed(2);
  if (Math.abs(parseFloat(elR.value) - r) > 1e-6) elR.value = r.toFixed(2);
  elRead.innerHTML =
    `r      = ${r.toFixed(2)}  ( ${(r / R1).toFixed(2)} r₁ )<br>` +
    `A(r)   = ${A.toFixed(3)}  ( ${Aratio.toFixed(2)} A₁ )<br>` +
    `I(r)   = ${I.toFixed(3)}  ( ${I.toFixed(2)} I₁ )<br>` +
    `E_max  ∝ ${(Math.sqrt(I)).toFixed(3)} E₁`;
}

/* ── controls ──────────────────────────────────────────────────────────── */
let tween = null;
function setR(r) { curR = Math.min(R2, Math.max(R1, r)); update(); }

elR.addEventListener('input', () => { tween = null; setR(parseFloat(elR.value)); });

function setMode(m) {
  mode = m;
  btnArea.classList.toggle('active', m === 'area');
  btnInt.classList.toggle('active', m === 'intensity');
  update();
}
btnArea.addEventListener('click', () => setMode('area'));
btnInt.addEventListener('click', () => setMode('intensity'));

/* ── guided demo ───────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'Near patch A₁', narration: 'The four rays leaving the radio source intercept a small square of area A₁ at distance r₁. All of the beam’s power crosses this patch.', distance: 3, overlay: 'area' },
  { title: 'Slide out to A₂', narration: 'Push the patch out to r₂ = 2r₁. The identical ray bundle now spans a square with twice the side and four times the area: A₂ = 4A₁.', distance: 6, overlay: 'area' },
  { title: 'Read it as intensity', narration: 'Same geometry, different label: the fixed power now spreads over four times the area, so the intensity has dropped to one quarter — the inverse-square law.', distance: 6, overlay: 'intensity' },
  { title: 'Back in close', narration: 'Bringing the patch back to r₁ restores the full intensity, confirming I ∝ 1/r² and E_max ∝ 1/r.', distance: 3, overlay: 'intensity' }
];
let stepIdx = 0, playing = false, playTimer = null;
const elTitle = document.getElementById('stepTitle');
const elNarr = document.getElementById('narr');

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  elTitle.textContent = `${stepIdx + 1}/${STEPS.length} · ${s.title}`;
  elNarr.textContent = s.narration;
  setMode(s.overlay);
  tween = { from: curR, to: s.distance, t0: performance.now(), dur: 900 };
}
document.getElementById('stepNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
document.getElementById('stepPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
const btnPlay = document.getElementById('stepPlay');
function stopPlay() { playing = false; clearTimeout(playTimer); btnPlay.textContent = 'Play'; btnPlay.classList.remove('active'); }
btnPlay.addEventListener('click', () => {
  if (playing) { stopPlay(); return; }
  playing = true; btnPlay.textContent = 'Stop'; btnPlay.classList.add('active');
  let k = 0;
  const run = () => {
    if (!playing) return;
    goToStep(k % STEPS.length);
    k++;
    if (k <= STEPS.length * 2) playTimer = setTimeout(run, 2600); else stopPlay();
  };
  run();
});

function tick() {
  requestAnimationFrame(tick);
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    setR(tween.from + (tween.to - tween.from) * e);
    if (k >= 1) tween = null;
  }
}
tick();

goToStep(0);
tween = null;
setR(R1);
// @FIGURE_CODE_END

