  a1Anchor.clone().addScaledVector(PR, 0.16).addScaledVector(PU, -0.07),
  c1.clone().addScaledVector(PU, h1 + 0.03).addScaledVector(PR, -h1 * 0.35),
  PU, 0.10);
const a2Anchor = c2.clone().addScaledVector(PR, 0.92).addScaledVector(PU, 0.46);
curvedArrow(
  a2Anchor.clone().addScaledVector(PR, -0.20).addScaledVector(PU, -0.06),
  c2.clone().addScaledVector(PR, h2 * 0.55).addScaledVector(PU, h2 + 0.03),
  PU, 0.10);

/* ── camera: prescribed pose, then a projection-exact tight refit ──────── */
const FIT_PTS = [ORG.clone(), wStart.clone(), wStart.clone().addScaledVector(PR, -0.28),
  a1Anchor.clone(), a2Anchor.clone(),
  mid1.clone().addScaledVector(PU, 0.24), mid2.clone().addScaledVector(PU, 0.24),
  mid2.clone().addScaledVector(OFF, 0.18),
  ...patchCorners(R1), ...C2,
  c2.clone().addScaledVector(PR, h2 + 0.9)];

function refit() {
  const FX = 0.80, FY = 0.86;
  for (let it = 0; it < 12; it++) {
    camera.updateMatrixWorld();
    let mnx = 1e9, mxx = -1e9, mny = 1e9, mxy = -1e9;
    for (const p of FIT_PTS) {
      const v = p.clone().project(camera);
      mnx = Math.min(mnx, v.x); mxx = Math.max(mxx, v.x);
      mny = Math.min(mny, v.y); mxy = Math.max(mxy, v.y);
    }
    const cx = (mnx + mxx) / 2, cy = (mny + mxy) / 2;
    const dist = camera.position.distanceTo(controls.target);
    const vfov = THREE.MathUtils.degToRad(camera.fov);
    const halfH = Math.tan(vfov / 2) * dist, halfW = halfH * (camera.aspect || 1);
    const rgt = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 0);
    const upv = new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld, 1);
    const shift = rgt.multiplyScalar(cx * halfW).add(upv.multiplyScalar(cy * halfH));
    camera.position.add(shift); controls.target.add(shift);
    const need = Math.max((mxx - mnx) / (2 * FX), (mxy - mny) / (2 * FY));
    const du = camera.position.clone().sub(controls.target).normalize();
    camera.position.copy(controls.target).addScaledVector(du, dist * Math.max(need, 0.05));
    camera.lookAt(controls.target);
    camera.near = 0.05;
    camera.far = dist * need + 60;
    camera.updateProjectionMatrix();
    controls.update();
