// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per drawn element) ───────────────────────────
   source dot            → SphereGeometry(0.05)                          black
   wavy leader           → Line (sine polyline) + tiny ConeGeometry tip   black
   4 solid rays          → Line  origin → live/near patch corner          #4A7F9B
   4 dashed rays         → Line  live corner → A2 corner (dashed)         #4A7F9B
   ghost patch A1        → PlaneGeometry fill + solid LineLoop outline    #7BA7BC/#4A7F9B
   ghost patch A2        → PlaneGeometry fill + dashed LineLoop           #7BA7BC/#4A7F9B
   live patch A(r)       → PlaneGeometry(1,1) scaled 0.20r + outline      steel blue
   r1 / r2 dimensions    → Line ∥ axis + 2 small cones + 2 end ticks      black
   A1 / A2 leaders       → QuadraticBezierCurve3 Line + small cone tip    black
   all text              → addLabel (serif italic maths)
  ───────────────────────────────────────────────────────────────────────── */

const COL_STROKE = 0x4a7f9b, COL_FILL = 0x7ba7bc, BLACK = 0x000000;
const R1 = 1.5, R2 = 3.0, KS = 0.20;                 // station radii, patch side = KS·r

/* Beam axis: under the prescribed camera (az 40°, el 18°) it projects
