const AX = new THREE.Vector3(0.628, 0.755, -0.188).normalize();
const PU = new THREE.Vector3(0, 1, 0).addScaledVector(AX, -0.755).normalize(); // patch up
const PR = new THREE.Vector3().crossVectors(PU, AX).normalize();               // patch right
const OFF = PU.clone().negate();            // perpendicular offset: below-right on screen
const PQ = new THREE.Quaternion().setFromRotationMatrix(
  new THREE.Matrix4().makeBasis(PR, PU, AX));
const ORG = new THREE.Vector3(0, 0, 0);

const hOf = r => KS * r * 0.5;
const patchCenter = r => AX.clone().multiplyScalar(r);
function patchCorners(r) {
  const h = hOf(r), c = patchCenter(r);
  return [[1, 1], [-1, 1], [-1, -1], [1, -1]].map(([a, b]) =>
    c.clone().addScaledVector(PR, a * h).addScaledVector(PU, b * h));
}

/* ── small helpers ─────────────────────────────────────────────────────── */
function lineFrom(pts, mat, order) {
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  if (mat.isLineDashedMaterial) l.computeLineDistances();
  if (order) l.renderOrder = order;
  scene.add(l); return l;
}
function setLinePts(line, pts) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
  if (line.material.isLineDashedMaterial) line.computeLineDistances();
}
