function coneAt(tip, dir, color, len = 0.065, rad = 0.020, onTop = false) {
  const m = new THREE.Mesh(new THREE.ConeGeometry(rad, len, 14),
    new THREE.MeshBasicMaterial({ color, depthTest: !onTop }));
  if (onTop) m.renderOrder = 6;
  const dn = dir.clone().normalize();
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dn);
  m.position.copy(tip).addScaledVector(dn, -len / 2);
  scene.add(m); return m;
}
