  const mid = from.clone().add(to).multiplyScalar(0.5).addScaledVector(bulgeDir, bulge);
  const pts = new THREE.QuadraticBezierCurve3(from, mid, to).getPoints(40);
  lineFrom(pts, new THREE.LineBasicMaterial({ color: BLACK, depthTest: false }), 6);
  const a = pts[pts.length - 2], b = pts[pts.length - 1];
  coneAt(b, b.clone().sub(a), BLACK, 0.055, 0.017, true);
