const dot = new THREE.Mesh(new THREE.SphereGeometry(0.05, 20, 16),
  new THREE.MeshBasicMaterial({ color: BLACK }));
scene.add(dot);
registerInteractive(dot, {
  title: 'Radio source',
  tooltip: 'Point source of radiation',
  body: 'A point transmitter radiating total power P. Every ray in the bundle carries a fixed share of that power, no matter how far it travels.'
