    title: r === R1 ? 'Patch A₁' : 'Patch A₂',
    tooltip: r === R1 ? 'Near station, r = r₁' : 'Far station, r = 2r₁',
    body: r === R1
      ? 'At r₁ the four-ray bundle cuts a square of side 0.20·r₁. Call its area A₁ — all of the beam power crosses it.'
