const livePatch = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), liveMat);
livePatch.quaternion.copy(PQ);
scene.add(livePatch);
registerInteractive(livePatch, {
  title: 'Sampling patch A(r)',
  tooltip: 'Slide it with the Distance control',
  body: 'This square always exactly fills the fixed cone of four rays. Its side grows as 0.20·r, so A(r) = (0.20r)² ∝ r² and I = P/A ∝ 1/r².'
